    "DECISIONS": "H-34ece3 supported, H-620cc6 refuted, H-dec1ef refuted, H-1a5c05 supported.",
    "CONTEXT": "Tesla's revenue history appears to start in FY2011 because there are no XBRL facts (any concept) recorded for Tesla prior to that year, indicating that standard revenue concepts were not used in early filings."
  },
  "answer": {
    "summary": "Tesla has no XBRL facts of any kind before fiscal year 2011, and its first revenue facts using the standard us‑gaap concepts appear in FY2011. This indicates that Tesla did not tag the standard revenue elements in its earlier filings, likely because it was not required to do so as a smaller reporting company before its IPO and subsequent accelerated filer status.",
    "claims": [
      {
        "text": "Tesla has zero XBRL facts (any concept) before fiscal year 2011.",
        "evidence": ["E-f160de"]
      },
      {
        "text": "Tesla's revenue facts using the two standard us‑gaap concepts begin in fiscal year 2011 and continue through 2026.",
        "evidence": ["E-51869f"]
      },
      {
        "text": "There are no revenue facts for Tesla before FY2011 regardless of period_frame.",
        "evidence": ["E-f332d0"]
      }
    ],
    "inferences": [
      {
        "text": "The lack of XBRL facts before FY2011 likely reflects that Tesla was not required to tag standard revenue concepts as a smaller reporting company prior to its IPO and later accelerated filer status.",
        "basis": ["Claim 1 (E-f160de)", "Hypothesis H-1a5c05 supported"]
      },
      {
        "text": "The appearance of revenue facts from FY2011 onward aligns with Tesla's transition to mandatory XBRL reporting of standard revenue concepts after becoming a larger accelerated filer.",
        "basis": ["Claim 2 (E-51869f)", "Hypothesis H-34ece3 supported"]
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-34ece3",
        "status": "supported",
        "evidence": ["E-f160de", "E-f332d0"],
        "why": "No revenue facts appear before FY2011, consistent with the hypothesis that the standard us‑gaap revenue concepts were not used in early filings."
      },
      {
        "id": "H-620cc6",
        "status": "refuted",
        "evidence": ["E-f160de"],
        "why": "If Tesla had revenue but tagged it with zero or omitted values, we would still see XBRL rows (value_usd=0). The complete absence of any XBRL facts rules out this explanation."
      },
      {
        "id": "H-dec1ef",
        "status": "refuted",
        "evidence": ["E-f160de"],
        "why": "If early filings existed but were removed by a period_frame null filter, some XBRL facts (any concept) would still be present before FY2011. None are found."
      },
      {
        "id": "H-1a5c05",
        "status": "supported",
        "evidence": ["E-f160de", "E-51869f"],
        "why": "The shift from zero XBRL facts before FY2011 to standard revenue facts starting in FY2011 matches the hypothesis that Tesla's reporting status change triggered mandatory XBRL tagging of revenue."
      }
    ]
  }
}
